// ── Cálculo signo lunar (zodíaco sidéreo) ──────────────────────────────────
function moonSign(date) {
  const J2000 = new Date('2000-01-01T12:00:00Z').getTime();
  const days  = (date.getTime() - J2000) / 86400000;
  const L_tropical = (218.316 + 13.176396 * days) % 360;
  const L_sidereal  = ((L_tropical - 23.85) % 360 + 360) % 360;
  const SIGNS = [
    {sign:'Aries',      tipo:'fruto'},
    {sign:'Tauro',      tipo:'raiz'},
    {sign:'Géminis',    tipo:'flor'},
    {sign:'Cáncer',     tipo:'hoja'},
    {sign:'Leo',        tipo:'fruto'},
    {sign:'Virgo',      tipo:'raiz'},
    {sign:'Libra',      tipo:'flor'},
    {sign:'Escorpio',   tipo:'hoja'},
    {sign:'Sagitario',  tipo:'fruto'},
    {sign:'Capricornio',tipo:'raiz'},
    {sign:'Acuario',    tipo:'flor'},
    {sign:'Piscis',     tipo:'hoja'},
  ];
  return SIGNS[Math.floor(L_sidereal / 30) % 12];
}

// ── Fase lunar ─────────────────────────────────────────────────────────────
function moonPhase(date) {
  const REF = new Date('2000-01-06T18:14:00Z').getTime();
  const frac = (((date.getTime() - REF) % (29.530589*86400000)) + (29.530589*86400000)) % (29.530589*86400000) / (29.530589*86400000);
  if(frac < 0.03 || frac > 0.97) return 'Luna Nueva 🌑';
  if(frac < 0.22) return 'Luna Creciente 🌒';
  if(frac < 0.28) return 'Cuarto Creciente 🌓';
  if(frac < 0.47) return 'Luna Gibosa 🌔';
  if(frac < 0.53) return 'Luna Llena 🌕';
  if(frac < 0.72) return 'Luna Gibosa Menguante 🌖';
  if(frac < 0.78) return 'Cuarto Menguante 🌗';
  return 'Luna Menguante 🌘';
}

